import Animated, {
	runOnJS,
	useAnimatedStyle,
	useSharedValue,
	withDelay,
	withTiming
} from 'react-native-reanimated'
import { LottieAnimation } from './LottieAnimation'
import { useState } from 'react'
import { defineStyles } from '@/utils/defineStyles'
import { MotiView } from 'moti'

type LottieAnimationObject = {
	keypath: string
	source: string
	subTitle: string
}

const lottieAnimations: LottieAnimationObject[] = [
	{
		keypath: 'DesigningAnimation',
		source: require('../assets/animations/DesigningAnim.json'),
		subTitle: 'Finalizing designs'
	},
	{
		keypath: 'CodeAnimation',
		source: require('../assets/animations/CodeAnim.json'),
		subTitle: 'Reviewing code'
	},
	{
		keypath: 'ClickAnimation',
		source: require('../assets/animations/ClickAnim.json'),
		subTitle: 'Fine-tuning details'
	},
	{
		keypath: 'PageAnimation',
		source: require('../assets/animations/PageAnim.json'),
		subTitle: 'Flowing words onto page'
	}
]

export const LoopingAnimation = () => {
	const [currentAnimationIndex, setCurrentAnimationIndex] = useState(0)
	const [currentAnimation, setCurrentAnimation] =
		useState<LottieAnimationObject>(lottieAnimations[0])

	const opacity = useSharedValue(1)

	const playNextAnimation = () => {
		opacity.set(
			withTiming(0, { duration: 350 }, (isFinished) => {
				if (isFinished) {
					const nextAnimationIndex =
						currentAnimationIndex === lottieAnimations.length - 1
							? 0
							: currentAnimationIndex + 1
					runOnJS(setCurrentAnimation)(lottieAnimations[nextAnimationIndex])
					runOnJS(setCurrentAnimationIndex)(nextAnimationIndex)
					opacity.set(withDelay(200, withTiming(1, { duration: 350 })))
				}
			})
		)
	}

	const fadeStyle = useAnimatedStyle(() => ({
		opacity: opacity.get()
	}))

	return (
		<MotiView
			from={{ opacity: 0 }}
			animate={{ opacity: 1 }}
			transition={{
				type: 'timing',
				delay: 1000
			}}
			pointerEvents="none"
			style={styles.container}
		>
			<Animated.View style={[styles.lottieAnimationContainer, fadeStyle]}>
				<LottieAnimation
					key={currentAnimation.keypath}
					keypath={currentAnimation.keypath}
					source={currentAnimation.source}
					subTitle={currentAnimation.subTitle}
					playNextAnimation={playNextAnimation}
				/>
			</Animated.View>
		</MotiView>
	)
}

const styles = defineStyles({
	container: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center',
		zIndex: 2
	},
	lottieAnimationContainer: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center',
		gap: 20
	}
})
